                continue

            rows = dict(conn.execute(
                "SELECT name, balance FROM accounts WHERE name IN (?, ?)",
                (source, target),
            ))
            if source not in rows or target not in rows:
                statuses.append("unknown")
                continue

            source_balance = decode_balance(rows[source])
            if source_balance < amount:
                statuses.append("insufficient")
                continue

